// 클래스 없이 최상위에 바로 선언한다
val APP = "kotlin-lab"

fun abs2(n: Int): Int {
    // TODO: if 를 식으로 써서 표현식 본문 한 줄로
    if (n < 0) {
        return -n
    } else {
        return n
    }
}

fun fee(age: Int): Int {
    // TODO: return 세 개를 if 식 하나로
    if (age < 8) {
        return 0
    } else if (age < 20) {
        return 5000
    } else {
        return 9000
    }
}

fun log(message: String) {
    // TODO: 이 함수가 반환하는 타입은? 생략하지 말고 명시할 것
    println("[" + APP + "] " + message)
}

fun main() {
    log("start")
    println(abs2(-7))
    println(fee(5))
    println(fee(15))
    println(fee(40))
    val tag = if (fee(40) > 8000) "adult" else "child"
    println(tag)
    val r = log("done")
    println(r)
}
